def sig(text): return frozenset(w for w in text.lower().split() if w not in STOP)
idx = {}
def store(finding):
    s = sig(finding)
    idx[s] = finding  # same signature -> update, not duplicate
    return s
print('sig:', store('inverted index speeds search past ten thousand documents'))
print('entries:', len(idx))

